package com.example.mini4x.sim

import kotlin.math.ceil
import kotlin.math.max

object CommandEngine {
    fun execute(state:SimState,command:Command):CommandResult { val reason=validate(state,command);if(reason!=null)return CommandResult(false,reason,listOf(SimEvent(EventType.COMMAND_REJECTED,command.playerId,message=reason)));val events=mutableListOf<SimEvent>();apply(state,command,events);state.actionSerial++;DerivedState.recalculateAll(state,events);return CommandResult(true,events=events) }
    fun validate(state:SimState,command:Command):String? {if(state.finished)return"Game is finished";if(command.playerId !in state.players.indices)return"Unknown player";if(state.activePlayer!=command.playerId)return"Not this player's turn";if(state.players[command.playerId].eliminated)return"Player is eliminated";return when(command){is MoveUnit->validateMove(state,command);is AttackUnit->validateAttack(state,command);is RecoverUnit->validateRecover(state,command);is TrainUnit->validateTrain(state,command);is BuyTechnology->validateTech(state,command);is HarvestResource->validateHarvest(state,command);is BuildImprovement->validateImprovement(state,command);is ChooseCityReward->validateReward(state,command);is CaptureCity->validateCapture(state,command);is ExamineRuin->validateRuin(state,command);is BuildRoad->validateRoad(state,command);is EstablishEmbassy->validateEmbassy(state,command);is OfferPeace->validatePeaceOffer(state,command);is BreakPeace->validateBreakPeace(state,command);is UpgradeShip->validateShip(state,command);is GatherStarfish->validateStarfish(state,command);is SpecialAction->validateSpecial(state,command);is EndTurn->null}}
    private fun ownUnit(state:SimState,pid:Int,id:Int)=state.unit(id)?.takeIf{it.owner==pid};private fun ownCity(state:SimState,pid:Int,id:Int)=state.city(id)?.takeIf{it.owner==pid}
    private fun validateMove(state:SimState,c:MoveUnit):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.frozenTurns>0)return"Unit is frozen";if(u.moved)return"Unit already moved";if(c.destination !in state.discoveredTiles[c.playerId])return"Destination is still unexplored";val dest=state.tile(c.destination)?:return"Outside map";if(dest.occupantUnitId!=null)return"Tile is occupied";val city=dest.cityId?.let(state::city);if(city!=null&&city.owner!=c.playerId&&state.diplomacy[c.playerId][city.owner]==Relation.PEACE)return"Cannot occupy an ally city while at peace";return if(MovementRules.findPath(state,u,c.destination)==null)"Destination is not reachable"else null}
    private fun validateAttack(state:SimState,c:AttackUnit):String?{val a=ownUnit(state,c.playerId,c.attackerId)?:return"Attacker not found";val d=state.unit(c.defenderId)?:return"Defender not found";return CombatRules.canAttack(state,a,d)}
    private fun validateRecover(state:SimState,c:RecoverUnit):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.tookAction)return"Unit already acted";if(!u.poisoned&&u.hp>=UnitCatalog.maxHP(u))return"Unit is already healthy";return null}
    private fun unlockTech(kind:UnitKind)=when(kind){UnitKind.WARRIOR->null;UnitKind.RIDER->"riding";UnitKind.ARCHER->"archery";UnitKind.DEFENDER->"strategy";UnitKind.SWORDSMAN->"smithery";UnitKind.MIND_BENDER->"philosophy";UnitKind.CATAPULT->"mathematics";UnitKind.CLOAK->"diplomacy";UnitKind.KNIGHT->"chivalry";else->"__reward_only__"}
    private fun validateTrain(state:SimState,c:TrainUnit):String?{val city=ownCity(state,c.playerId,c.cityId)?:return"City not found";if(city.pendingRewardLevel!=null)return"Choose the city's upgrade reward first";if(state.tile(city.pos)?.occupantUnitId!=null)return"City tile is occupied";if(city.supportedUnitIds.count{state.unit(it)?.owner==c.playerId}>=city.capacity)return"City unit capacity is full";val tech=unlockTech(c.kind);if(tech=="__reward_only__")return"This unit cannot be trained normally";if(tech!=null&&tech !in state.players[c.playerId].technologies)return"Research ${TechnologyCatalog[tech].label} first";val cost=UnitCatalog[c.kind].cost?:return"Unit cannot be purchased";if(state.players[c.playerId].stars<cost)return"Not enough stars";return null}
    private fun validateTech(state:SimState,c:BuyTechnology):String?{runCatching{TechnologyCatalog[c.technologyId]}.getOrElse{return"Unknown technology"};if(!TechnologyCatalog.canResearch(state,c.playerId,c.technologyId))return"Prerequisite is not researched";val cost=TechnologyCatalog.researchCost(state,c.playerId,c.technologyId);return if(state.players[c.playerId].stars<cost)"Not enough stars"else null}
    private fun validateHarvest(state:SimState,c:HarvestResource):String?{val t=state.tile(c.pos)?:return"Outside map";if(t.territoryOwner!=c.playerId)return"Resource is outside your territory";val r=t.resource?:return"No harvestable resource";val tech=when(r){Resource.FRUIT->"organization";Resource.ANIMAL->"hunting";Resource.FISH->"fishing";Resource.CROP,Resource.ORE->return"This resource requires an improvement"};if(tech !in state.players[c.playerId].technologies)return"Research ${TechnologyCatalog[tech].label} first";if(state.players[c.playerId].stars<2)return"Not enough stars";if(DerivedState.cityForTile(state,c.playerId,c.pos)==null)return"Tile is not attached to a city";return null}
    private fun validateImprovement(state:SimState,c:BuildImprovement):String?{val t=state.tile(c.pos)?:return"Outside map";if(t.territoryOwner!=c.playerId)return"Tile is outside your territory";if(t.cityId!=null||t.village)return"Tile is occupied by a settlement";if(t.improvement!=null)return"Tile already has an improvement";val rule=ImprovementRules.rules[c.improvement]?:return"Improvement unavailable";if(rule.tech!=null&&rule.tech !in state.players[c.playerId].technologies)return"Research ${TechnologyCatalog[rule.tech].label} first";if(t.terrain !in rule.terrain)return"Wrong terrain for this improvement";if(c.improvement==Improvement.FARM&&t.resource!=Resource.CROP)return"Farm requires crops";if(c.improvement==Improvement.MINE&&t.resource!=Resource.ORE)return"Mine requires ore";if(c.improvement==Improvement.PORT&&t.terrain!=Terrain.WATER)return"Port requires shallow water";if(c.improvement==Improvement.BRIDGE){val horizontal=listOf(Pos(c.pos.x-1,c.pos.y),Pos(c.pos.x+1,c.pos.y)).all{q->state.tile(q)?.terrain !in setOf(null,Terrain.WATER,Terrain.OCEAN)};val vertical=listOf(Pos(c.pos.x,c.pos.y-1),Pos(c.pos.x,c.pos.y+1)).all{q->state.tile(q)?.terrain !in setOf(null,Terrain.WATER,Terrain.OCEAN)};if(!horizontal&&!vertical)return"Bridge must connect opposite land cells"};if(DerivedState.cityForTile(state,c.playerId,c.pos)==null)return"Tile is not attached to a city";return if(state.players[c.playerId].stars<rule.cost)"Not enough stars"else null}
    private fun validateReward(state:SimState,c:ChooseCityReward):String?{val city=ownCity(state,c.playerId,c.cityId)?:return"City not found";val lvl=city.pendingRewardLevel?:return"City has no pending reward";val legal=when(lvl){2->setOf(CityRewardType.WORKSHOP,CityRewardType.EXPLORER);3->setOf(CityRewardType.WALL,CityRewardType.STARS_5);4->setOf(CityRewardType.BORDER_GROWTH,CityRewardType.POPULATION_3);else->setOf(CityRewardType.PARK,CityRewardType.SUPER_UNIT)};if(c.reward !in legal)return"Reward is not available at level $lvl";if(c.reward==CityRewardType.SUPER_UNIT&&state.tile(city.pos)?.occupantUnitId!=null)return"City tile must be empty for a super unit";return null}
    private fun validateCapture(state:SimState,c:CaptureCity):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.tookAction)return"Unit already acted";val t=state.tile(u.pos)?:return"Outside map";val enemyCity=t.cityId?.let(state::city)?.takeIf{it.owner!=c.playerId};if(!t.village&&enemyCity==null)return"No village or enemy city here";if(enemyCity!=null&&state.diplomacy[c.playerId][enemyCity.owner]==Relation.PEACE)return"Cannot capture an ally city";if(u.captureReadyOnRound==null||state.roundNumber<u.captureReadyOnRound!!)return"Occupier must survive until its next turn";return null}
    private fun validateRuin(state:SimState,c:ExamineRuin):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.tookAction)return"Unit already acted";if(state.tile(u.pos)?.ruin!=true)return"Unit is not standing on a ruin";return null}
    private fun validateRoad(state:SimState,c:BuildRoad):String?{if("roads" !in state.players[c.playerId].technologies)return"Research Roads first";val t=state.tile(c.pos)?:return"Outside map";if(t.territoryOwner!=c.playerId)return"Road must be in your territory";if(t.road)return"Road already exists";if(t.terrain in setOf(Terrain.MOUNTAIN,Terrain.WATER,Terrain.OCEAN))return"Road cannot be built here";return if(state.players[c.playerId].stars<3)"Not enough stars"else null}
    private fun validateEmbassy(state:SimState,c:EstablishEmbassy):String?{if("diplomacy" !in state.players[c.playerId].technologies)return"Research Diplomacy first";if(c.targetPlayerId !in state.players.indices||c.targetPlayerId==c.playerId)return"Invalid target";if(c.targetPlayerId !in state.players[c.playerId].metPlayers)return"You have not met this civilization";if(c.targetPlayerId in state.players[c.playerId].embassies)return"Embassy already exists";val cost=5+state.players[c.playerId].embassies.size*3;return if(state.players[c.playerId].stars<cost)"Not enough stars"else null}
    private fun validatePeaceOffer(state:SimState,c:OfferPeace):String?{if("strategy" !in state.players[c.playerId].technologies)return"Research Strategy first";if(c.targetPlayerId !in state.players.indices||c.targetPlayerId==c.playerId)return"Invalid target";if(state.diplomacy[c.playerId][c.targetPlayerId]==Relation.PEACE)return"Already at peace";return null}
    private fun validateBreakPeace(state:SimState,c:BreakPeace):String?{if(c.targetPlayerId !in state.players.indices||state.diplomacy[c.playerId][c.targetPlayerId]!=Relation.PEACE)return"No peace treaty exists";return null}
    private fun validateShip(state:SimState,c:UpgradeShip):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.kind !in setOf(UnitKind.RAFT,UnitKind.RAMMER,UnitKind.SCOUT,UnitKind.BOMBER))return"Unit is not a transport";val(tech,cost)=when(c.target){UnitKind.RAMMER->"ramming" to 5;UnitKind.SCOUT->"sailing" to 5;UnitKind.BOMBER->"navigation" to 15;else->return"Invalid ship upgrade"};if(tech !in state.players[c.playerId].technologies)return"Research ${TechnologyCatalog[tech].label} first";if(state.players[c.playerId].stars<cost)return"Not enough stars";return null}
    private fun validateStarfish(state:SimState,c:GatherStarfish):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if("navigation" !in state.players[c.playerId].technologies)return"Research Navigation first";if(state.tile(u.pos)?.starfish!=true)return"No starfish here";if(u.tookAction)return"Unit already acted";return null}
    private fun validateSpecial(state:SimState,c:SpecialAction):String?{val u=ownUnit(state,c.playerId,c.unitId)?:return"Unit not found";if(u.tookAction)return"Unit already acted";return when(c.action){SpecialActionType.HEAL_ADJACENT->if(Skill.HEAL !in UnitCatalog.skills(u))"Unit cannot heal"else null;SpecialActionType.INFILTRATE->{if(u.kind!=UnitKind.CLOAK)return"Only Cloaks can infiltrate";val target=c.targetPos?.let(state::cityAt)?:return"Choose an enemy city";if(target.owner==c.playerId||u.pos.chebyshev(target.pos)>1)return"Cloak must be adjacent to an enemy city";if(state.diplomacy[c.playerId][target.owner]==Relation.PEACE)return"Cannot infiltrate an ally";null};SpecialActionType.DISBAND->if("free_spirit" !in state.players[c.playerId].technologies)"Research Free Spirit first"else null;SpecialActionType.DESTROY_BUILDING->{if("chivalry" !in state.players[c.playerId].technologies)return"Research Chivalry first";val t=c.targetPos?.let(state::tile)?:return"Choose a building";if(t.territoryOwner!=c.playerId||t.improvement==null)"Choose one of your improvements"else null}}}
    private fun spend(state:SimState,pid:Int,amount:Int,events:MutableList<SimEvent>,why:String){state.players[pid].stars-=amount;events+=SimEvent(EventType.STARS_CHANGED,pid,amount=-amount,message=why)}
    private fun gain(state:SimState,pid:Int,amount:Int,events:MutableList<SimEvent>,why:String){state.players[pid].stars+=amount;events+=SimEvent(EventType.STARS_CHANGED,pid,amount=amount,message=why)}
    private fun removeUnit(state:SimState,u:UnitState,events:MutableList<SimEvent>,killer:Int?=null){state.tile(u.pos)?.takeIf{it.occupantUnitId==u.id}?.occupantUnitId=null;u.supportCityId?.let{state.city(it)?.supportedUnitIds?.remove(u.id)};state.units.remove(u);state.players[u.owner].losses++;killer?.let{state.players[it].kills++};events+=SimEvent(EventType.UNIT_KILLED,killer,subjectId=u.id,to=u.pos,message="Unit defeated")}
    private fun apply(state:SimState,c:Command,events:MutableList<SimEvent>){when(c){is MoveUnit->applyMove(state,c,events);is AttackUnit->applyAttack(state,c,events);is RecoverUnit->applyRecover(state,c,events);is TrainUnit->applyTrain(state,c,events);is BuyTechnology->applyTech(state,c,events);is HarvestResource->applyHarvest(state,c,events);is BuildImprovement->applyImprovement(state,c,events);is ChooseCityReward->applyReward(state,c,events);is CaptureCity->applyCapture(state,c,events);is ExamineRuin->applyRuin(state,c,events);is BuildRoad->{spend(state,c.playerId,3,events,"Road");state.tile(c.pos)!!.road=true;events+=SimEvent(EventType.ROAD_BUILT,c.playerId,to=c.pos)};is EstablishEmbassy->applyEmbassy(state,c,events);is OfferPeace->{state.diplomacy[c.playerId][c.targetPlayerId]=Relation.PEACE;state.diplomacy[c.targetPlayerId][c.playerId]=Relation.PEACE;events+=SimEvent(EventType.PEACE_OFFERED,c.playerId,targetId=c.targetPlayerId,message="Peace established")};is BreakPeace->applyBreakPeace(state,c,events);is UpgradeShip->applyShip(state,c,events);is GatherStarfish->{val u=state.unit(c.unitId)!!;state.tile(u.pos)!!.starfish=false;u.tookAction=true;gain(state,c.playerId,8,events,"Starfish");events+=SimEvent(EventType.STARFISH_GATHERED,c.playerId,subjectId=u.id,to=u.pos,amount=8)};is SpecialAction->applySpecial(state,c,events);is EndTurn->applyEndTurn(state,c,events)}}
    private fun applyMove(state:SimState,c:MoveUnit,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;val mp=MovementRules.findPath(state,u,c.destination)!!;var last=u.pos;for(step in mp.path){state.tile(last)?.takeIf{it.occupantUnitId==u.id}?.occupantUnitId=null;u.pos=step;state.tile(step)!!.occupantUnitId=u.id;if(mp.embarked&&!MovementRules.isNaval(u.kind)&&state.tile(step)!!.terrain in setOf(Terrain.WATER,Terrain.OCEAN)){val carried=u.kind;u.carriedKind=carried;u.kind=if(carried==UnitKind.GIANT)UnitKind.JUGGERNAUT else UnitKind.RAFT};if(MovementRules.isNaval(u.kind)&&state.tile(step)!!.terrain !in setOf(Terrain.WATER,Terrain.OCEAN)&&u.carriedKind!=null){u.kind=u.carriedKind!!;u.carriedKind=null};events+=SimEvent(EventType.UNIT_MOVED,c.playerId,subjectId=u.id,from=last,to=step);last=step;VisionRules.revealUnit(state,u,events);if(Skill.STOMP in UnitCatalog.skills(u)){for(q in step.neighbours8()){val enemy=state.tile(q)?.occupantUnitId?.let(state::unit)?.takeIf{it.owner!=u.owner}?:continue;enemy.hp-=5;events+=SimEvent(EventType.UNIT_DAMAGED,u.owner,subjectId=enemy.id,amount=5,from=step,to=q,message="Stomp");if(enemy.hp<=0)removeUnit(state,enemy,events,u.owner)}}};u.moved=true;u.tookAction=true;val t=state.tile(u.pos)!!;val enemyCity=t.cityId?.let(state::city)?.takeIf{it.owner!=u.owner};if(t.village||enemyCity!=null){u.captureReadyOnRound=state.roundNumber+1;if(enemyCity!=null){enemyCity.besiegedByUnitId=u.id;events+=SimEvent(EventType.CITY_BESIEGED,u.owner,subjectId=enemyCity.id,targetId=u.id,to=u.pos,message="City under siege")}}else u.captureReadyOnRound=null}
    private fun applyAttack(state:SimState,c:AttackUnit,events:MutableList<SimEvent>){val a=state.unit(c.attackerId)!!;val d=state.unit(c.defenderId)!!;if(Skill.CONVERT in UnitCatalog.skills(a)){val old=d.owner;d.owner=a.owner;d.supportCityId=null;d.independent=true;a.attacked=true;a.tookAction=true;events+=SimEvent(EventType.UNIT_CONVERTED,a.owner,subjectId=d.id,targetId=old,to=d.pos,message="Unit converted");return};val pv=CombatRules.preview(state,a,d);val dPos=d.pos;d.hp-=pv.damageToDefender;events+=SimEvent(EventType.UNIT_DAMAGED,a.owner,subjectId=d.id,targetId=a.id,from=a.pos,to=d.pos,amount=pv.damageToDefender);if(Skill.SPLASH in UnitCatalog.skills(a)){val spl=CombatRules.splashDamage(pv.damageToDefender);if(spl>0)for(q in dPos.neighbours8()){val other=state.tile(q)?.occupantUnitId?.let(state::unit)?.takeIf{it.owner!=a.owner&&it.id!=d.id}?:continue;other.hp-=spl;events+=SimEvent(EventType.UNIT_DAMAGED,a.owner,subjectId=other.id,targetId=a.id,to=q,amount=spl,message="Splash");if(other.hp<=0)removeUnit(state,other,events,a.owner)}};var killed=false;if(d.hp<=0){killed=true;a.kills++;removeUnit(state,d,events,a.owner)}else if(pv.retaliation>0){a.hp-=pv.retaliation;events+=SimEvent(EventType.UNIT_DAMAGED,d.owner,subjectId=a.id,targetId=d.id,from=d.pos,to=a.pos,amount=pv.retaliation,message="Retaliation");if(a.hp<=0){removeUnit(state,a,events,d.owner);return}};a.attacked=true;a.tookAction=true;if(killed&&UnitCatalog[a.kind].range==1&&state.unit(a.id)!=null&&state.tile(dPos)?.occupantUnitId==null){state.tile(a.pos)?.takeIf{it.occupantUnitId==a.id}?.occupantUnitId=null;val old=a.pos;a.pos=dPos;state.tile(dPos)!!.occupantUnitId=a.id;events+=SimEvent(EventType.UNIT_MOVED,a.owner,subjectId=a.id,from=old,to=dPos,message="Advance");VisionRules.revealUnit(state,a,events)};if(killed&&Skill.PERSIST in UnitCatalog.skills(a))a.attacked=false;if(Skill.ESCAPE in UnitCatalog.skills(a))a.moved=false}
    private fun applyRecover(state:SimState,c:RecoverUnit,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;u.tookAction=true;if(u.poisoned){u.poisoned=false;events+=SimEvent(EventType.UNIT_HEALED,c.playerId,subjectId=u.id,message="Poison removed");return};val own=state.tile(u.pos)?.territoryOwner==u.owner;val heal=if(own)4 else 2;val before=u.hp;u.hp=(u.hp+heal).coerceAtMost(UnitCatalog.maxHP(u));events+=SimEvent(EventType.UNIT_HEALED,c.playerId,subjectId=u.id,amount=u.hp-before,to=u.pos)}
    private fun applyTrain(state:SimState,c:TrainUnit,events:MutableList<SimEvent>){val city=state.city(c.cityId)!!;val cost=UnitCatalog[c.kind].cost!!;spend(state,c.playerId,cost,events,"Train ${c.kind}");val kind=FactionCatalog[state.players[c.playerId].factionId].unitReplacementMap[c.kind]?:c.kind;val u=UnitState(state.nextUnitId++,c.playerId,city.pos,kind,UnitCatalog[kind].maxHP,supportCityId=city.id);state.units+=u;city.supportedUnitIds+=u.id;state.tile(city.pos)!!.occupantUnitId=u.id;VisionRules.revealUnit(state,u,events)}
    private fun applyTech(state:SimState,c:BuyTechnology,events:MutableList<SimEvent>){val cost=TechnologyCatalog.researchCost(state,c.playerId,c.technologyId);spend(state,c.playerId,cost,events,"Research ${TechnologyCatalog[c.technologyId].label}");state.players[c.playerId].technologies+=c.technologyId;events+=SimEvent(EventType.TECH_RESEARCHED,c.playerId,message=c.technologyId,amount=cost);VisionRules.revealAllSources(state,c.playerId,events)}
    private fun applyHarvest(state:SimState,c:HarvestResource,events:MutableList<SimEvent>){val t=state.tile(c.pos)!!;val r=t.resource!!;val city=DerivedState.cityForTile(state,c.playerId,c.pos)!!;spend(state,c.playerId,2,events,"Harvest $r");t.resource=null;t.workCityId=city.id;city.basePopulation+=1;events+=SimEvent(EventType.RESOURCE_USED,c.playerId,subjectId=city.id,to=c.pos,amount=1,message=r.name)}
    private fun applyImprovement(state:SimState,c:BuildImprovement,events:MutableList<SimEvent>){val t=state.tile(c.pos)!!;val rule=ImprovementRules.rules[c.improvement]!!;val city=DerivedState.cityForTile(state,c.playerId,c.pos)!!;spend(state,c.playerId,rule.cost,events,"Build ${c.improvement}");t.improvement=c.improvement;t.workCityId=city.id;t.improvementBuiltTurn=state.roundNumber;if(c.improvement in setOf(Improvement.FARM,Improvement.MINE))t.resource=null;if(c.improvement==Improvement.BRIDGE)t.road=true;events+=SimEvent(EventType.IMPROVEMENT_BUILT,c.playerId,subjectId=city.id,to=c.pos,message=c.improvement.name)}
    private fun applyReward(state:SimState,c:ChooseCityReward,events:MutableList<SimEvent>){val city=state.city(c.cityId)!!;when(c.reward){CityRewardType.WORKSHOP->city.workshop=true;CityRewardType.EXPLORER->runExplorer(state,c.playerId,city,events);CityRewardType.WALL->city.wall=true;CityRewardType.STARS_5->gain(state,c.playerId,5,events,"City reward");CityRewardType.BORDER_GROWTH->{city.borderExpanded=true;DerivedState.claimCityTerritory(state,city)};CityRewardType.POPULATION_3->city.basePopulation+=3;CityRewardType.PARK->city.park=true;CityRewardType.SUPER_UNIT->{val u=UnitState(state.nextUnitId++,c.playerId,city.pos,UnitKind.GIANT,40,supportCityId=city.id);state.units+=u;city.supportedUnitIds+=u.id;state.tile(city.pos)!!.occupantUnitId=u.id;VisionRules.revealUnit(state,u,events)}};city.pendingRewardLevel=null;events+=SimEvent(EventType.CITY_REWARD,c.playerId,subjectId=city.id,message=c.reward.name)}
    private fun runExplorer(state:SimState,pid:Int,city:City,events:MutableList<SimEvent>){var pos=city.pos;val visited=mutableSetOf(pos);repeat(12){val candidates=pos.neighbours8().filter(state::inBounds);val best=candidates.maxByOrNull{q->val reveal=(q.x-1..q.x+1).sumOf{x->(q.y-1..q.y+1).count{y->Pos(x,y).let{state.inBounds(it)&&it !in state.discoveredTiles[pid]}}};reveal*100-(if(q in visited)50 else 0)+deterministicInt(state,97+it,10)}?:return@repeat;pos=best;visited+=pos;VisionRules.revealFrom(state,pid,pos,1,events)}}
    private fun applyCapture(state:SimState,c:CaptureCity,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;val t=state.tile(u.pos)!!;if(t.village){t.village=false;val city=City(state.nextCityId++,c.playerId,u.pos,level=1,originalOwner=c.playerId);state.cities+=city;t.cityId=city.id;u.supportCityId?.let{state.city(it)?.supportedUnitIds?.remove(u.id)};u.supportCityId=city.id;city.supportedUnitIds+=u.id;DerivedState.claimCityTerritory(state,city);events+=SimEvent(EventType.VILLAGE_CAPTURED,c.playerId,subjectId=city.id,targetId=u.id,to=u.pos)}else{val city=state.city(t.cityId!!)!!;val old=city.owner;city.owner=c.playerId;city.besiegedByUnitId=null;u.supportCityId?.let{state.city(it)?.supportedUnitIds?.remove(u.id)};u.supportCityId=city.id;city.supportedUnitIds+=u.id;DerivedState.claimCityTerritory(state,city);events+=SimEvent(EventType.CITY_CAPTURED,c.playerId,subjectId=city.id,targetId=old,to=u.pos);if(state.ownedCities(old).isEmpty())state.players[c.playerId].opponentsDefeated++};u.tookAction=true;u.captureReadyOnRound=null}
    private fun applyRuin(state:SimState,c:ExamineRuin,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;val t=state.tile(u.pos)!!;t.ruin=false;u.tookAction=true;val outcome=deterministicInt(state,701,5);val msg=when(outcome){0->{gain(state,c.playerId,10,events,"Ruin");"+10 stars"};1->{val eligible=TechnologyCatalog.all.filter{it.id !in state.players[c.playerId].technologies&&TechnologyCatalog.canResearch(state,c.playerId,it.id)};if(eligible.isNotEmpty()){val tech=eligible[deterministicInt(state,702,eligible.size)];state.players[c.playerId].technologies+=tech.id;events+=SimEvent(EventType.TECH_RESEARCHED,c.playerId,message=tech.id);"Free ${tech.label}"}else{gain(state,c.playerId,10,events,"Ruin");"+10 stars"}};2->{state.capital(c.playerId)?.basePopulation=(state.capital(c.playerId)?.basePopulation?:0)+3;"+3 capital population"};3->{runExplorer(state,c.playerId,state.capital(c.playerId)?:state.ownedCities(c.playerId).first(),events);"Explorer"};else->{val candidates=listOf(UnitKind.WARRIOR,UnitKind.RIDER,UnitKind.ARCHER,UnitKind.DEFENDER,UnitKind.SWORDSMAN).filter{k->unlockTech(k)?.let{it in state.players[c.playerId].technologies}?:true};val kind=candidates[deterministicInt(state,703,candidates.size)];val pos=u.pos.neighbours8().firstOrNull{q->state.tile(q)?.let{it.occupantUnitId==null&&it.terrain !in setOf(Terrain.WATER,Terrain.OCEAN)}==true};if(pos!=null){val nu=UnitState(state.nextUnitId++,c.playerId,pos,kind,UnitCatalog[kind].maxHP,veteran=true,independent=true);state.units+=nu;state.tile(pos)!!.occupantUnitId=nu.id};"Veteran unit"}};events+=SimEvent(EventType.RUIN_EXAMINED,c.playerId,subjectId=u.id,to=u.pos,message=msg)}
    private fun applyEmbassy(state:SimState,c:EstablishEmbassy,events:MutableList<SimEvent>){val cost=5+state.players[c.playerId].embassies.size*3;spend(state,c.playerId,cost,events,"Embassy");state.players[c.playerId].embassies+=c.targetPlayerId;state.capital(c.targetPlayerId)?.let{VisionRules.revealFrom(state,c.playerId,it.pos,1,events)};events+=SimEvent(EventType.EMBASSY_ESTABLISHED,c.playerId,targetId=c.targetPlayerId,amount=cost)}
    private fun applyBreakPeace(state:SimState,c:BreakPeace,events:MutableList<SimEvent>){val target=c.targetPlayerId;state.diplomacy[c.playerId][target]=Relation.WAR;state.diplomacy[target][c.playerId]=Relation.WAR;state.ownedUnits(c.playerId).toList().forEach{u->if(state.tile(u.pos)?.territoryOwner==target)removeUnit(state,u,events,null)};state.ownedUnits(c.playerId).forEach{it.moved=true;it.attacked=true;it.tookAction=true};state.players[c.playerId].embassies.remove(target);state.players[target].embassies.remove(c.playerId);events+=SimEvent(EventType.PEACE_BROKEN,c.playerId,targetId=target,message="Peace broken; remaining units frozen")}
    private fun applyShip(state:SimState,c:UpgradeShip,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;val cost=when(c.target){UnitKind.RAMMER,UnitKind.SCOUT->5;UnitKind.BOMBER->15;else->0};spend(state,c.playerId,cost,events,"Ship upgrade");u.kind=c.target;events+=SimEvent(EventType.SHIP_UPGRADED,c.playerId,subjectId=u.id,message=c.target.name)}
    private fun applySpecial(state:SimState,c:SpecialAction,events:MutableList<SimEvent>){val u=state.unit(c.unitId)!!;when(c.action){SpecialActionType.HEAL_ADJACENT->{for(q in u.pos.neighbours8()){val ally=state.tile(q)?.occupantUnitId?.let(state::unit)?.takeIf{it.owner==u.owner}?:continue;if(ally.poisoned)ally.poisoned=false else{val before=ally.hp;ally.hp=(ally.hp+4).coerceAtMost(UnitCatalog.maxHP(ally));events+=SimEvent(EventType.UNIT_HEALED,u.owner,subjectId=ally.id,amount=ally.hp-before,to=q)}};u.tookAction=true};SpecialActionType.INFILTRATE->{val city=state.cityAt(c.targetPos!!)!!;val count=city.level.coerceAtMost(5);var spawned=0;val cells=(city.pos.neighbours8()+city.pos).sortedBy{it.chebyshev(u.pos)};for(q in cells){if(spawned>=count)break;val t=state.tile(q)?:continue;if(t.occupantUnitId==null&&(t.territoryOwner==city.owner||q==city.pos)){val g=UnitState(state.nextUnitId++,u.owner,q,UnitKind.GUERRILLA,10,independent=true);state.units+=g;t.occupantUnitId=g.id;spawned++}};removeUnit(state,u,events,null);events+=SimEvent(EventType.UNIT_CONVERTED,c.playerId,subjectId=city.id,amount=spawned,message="Infiltration created $spawned guerrillas")};SpecialActionType.DISBAND->{val value=ceil((UnitCatalog[u.carriedKind?:u.kind].cost?:0)/2.0).toInt();removeUnit(state,u,events,null);if(value>0)gain(state,c.playerId,value,events,"Disband")};SpecialActionType.DESTROY_BUILDING->{val t=state.tile(c.targetPos!!)!!;t.improvement=null;t.workCityId=null;t.road=false;u.tookAction=true;events+=SimEvent(EventType.IMPROVEMENT_BUILT,c.playerId,to=t.pos,message="Building destroyed")}}}
    private fun applyEndTurn(state:SimState,c:EndTurn,events:MutableList<SimEvent>){for(u in state.ownedUnits(c.playerId).toList()){if(!u.tookAction&&(u.poisoned||u.hp<UnitCatalog.maxHP(u))){if(u.poisoned){u.poisoned=false;events+=SimEvent(EventType.UNIT_HEALED,c.playerId,subjectId=u.id,message="Poison removed")}else{val heal=if(state.tile(u.pos)?.territoryOwner==u.owner)4 else 2;val before=u.hp;u.hp=(u.hp+heal).coerceAtMost(UnitCatalog.maxHP(u));events+=SimEvent(EventType.UNIT_HEALED,c.playerId,subjectId=u.id,amount=u.hp-before,to=u.pos)}};if(u.frozenTurns>0)u.frozenTurns--};events+=SimEvent(EventType.TURN_ENDED,c.playerId,message="Turn ended");var next=c.playerId;var wrapped=false;do{next=(next+1)%state.players.size;if(next==0)wrapped=true}while(state.players[next].eliminated&&next!=c.playerId);if(wrapped)state.roundNumber++;state.activePlayer=next;beginTurn(state,next,true,events)}
    fun beginTurn(state:SimState,pid:Int,grantIncome:Boolean,events:MutableList<SimEvent>){state.ownedUnits(pid).forEach{u->u.moved=false;u.attacked=false;u.tookAction=false};if(grantIncome){val income=DerivedState.totalIncome(state,pid);if(income>0)gain(state,pid,income,events,"Turn income")};VisionRules.revealAllSources(state,pid,events);events+=SimEvent(EventType.TURN_STARTED,pid,amount=state.roundNumber,message="Round ${state.roundNumber}")}
    private fun deterministicInt(state:SimState,salt:Int,bound:Int):Int{if(bound<=1)return 0;var z=state.seed xor((state.rngCounter+++salt)*-7046029254386353131L);z=(z xor(z ushr 30))*-4658895280553007687L;z=(z xor(z ushr 27))*-7723592293110705685L;z=z xor(z ushr 31);return((z and Long.MAX_VALUE)%bound).toInt()}
}
